  const { attention } = row.look;

  if (attention !== null) {
    switch (attention.kind) {
      case "approval":
        return { taskId: id, text: `${id} waiting on your approval`, rank: 1 };
      case "question":
        return { taskId: id, text: `${id} asks you`, rank: 2 };
      case "handed":
        return { taskId: id, text: `${id}'s claim handed to you`, rank: 3 };
      case "stopped":
